<script lang="ts">import {goto} from '$app/navigation';import {auth} from '$lib/api';import {session} from '$lib/stores/session';import TopNav from '$lib/components/TopNav.svelte';let role=$state<'farmer'|'producer'>('farmer'),name=$state(''),email=$state(''),password=$state(''),error=$state(''),loading=$state(false);async function submit(){if(!name||!email||!password){error='Complete all fields.';return}loading=true;error='';try{const {user}=await auth.register({name,email,password,role});session.set(user);await goto('/dashboard')}catch(e){error=e instanceof Error?e.message:'Unable to create account.'}finally{loading=false}}</script>
<svelte:head><title>Register · RegenFeed</title></svelte:head><TopNav/><main class="auth-page register-page"><section class="auth-story"><a class="auth-brand" href="/">REGEN<span>FEED</span></a><div><p class="eyebrow light">JOIN THE CIRCULAR MARKETPLACE</p><h1>Give waste a<br/><em>next season.</em></h1><p>Connect with local businesses and farms while keeping useful organic material out of landfill.</p></div><div class="auth-proof"><i class="fa-solid fa-bolt"></i><span>Simple listings. Local pickup. Lightning settlement.</span></div></section><section class="auth-form-wrap"><form class="auth-card register-card" onsubmit={(e)=>{e.preventDefault();submit()}}><div><p class="eyebrow">CREATE YOUR ACCOUNT</p><h2>How will you use RegenFeed?</h2></div><div class="role-cards" role="group" aria-label="Choose account role"><button type="button" class:chosen={role==='farmer'} onclick={()=>role='farmer'}><i class="fa-solid fa-wheat-awn"></i><strong>Farmer</strong><small>Find and buy organic inputs</small></button><button type="button" class:chosen={role==='producer'} onclick={()=>role='producer'}><i class="fa-solid fa-hotel"></i><strong>Producer</strong><small>List and sell organic surplus</small></button></div>{#if error}<p class="error" role="alert">{error}</p>{/if}<label>{role==='farmer'?'Farm':'Business'} name<div class="input-shell"><i class="fa-regular fa-building"></i><input bind:value={name} autocomplete="organization" placeholder={role==='farmer'?'Your farm name':'Your business name'} required /></div></label><label>Email address<div class="input-shell"><i class="fa-regular fa-envelope"></i><input bind:value={email} type="email" autocomplete="email" placeholder="you@example.com" required /></div></label><label>Password<div class="input-shell"><i class="fa-solid fa-lock"></i><input bind:value={password} type="password" autocomplete="new-password" minlength="8" placeholder="At least 8 characters" required /></div></label><button class="btn primary auth-submit" disabled={loading}>{loading?'Creating account…':'Create account'} <i class="fa-solid fa-arrow-right"></i></button><p class="auth-switch">Already registered? <a href="/auth/login">Log in</a></p></form></section></main>
